function validate([traversal]) {
  if (typeof traversal !== 'string' || !/^[0-9-]+$/.test(traversal)) return 'traversal may only contain digits and dashes.';
  // children[d] counts the children already attached to the open node at depth d.
  const children = [];
  let index = 0, nodes = 0;
  while (index < traversal.length) {
    let depth = 0;
    while (traversal[index] === '-') { depth++; index++; }
    const start = index;
    while (index < traversal.length && traversal[index] !== '-') index++;
    const digits = traversal.slice(start, index);
    if (!digits) return 'Every run of dashes must be followed by a value.';
    if (digits[0] === '0' || digits.length > 10 || Number(digits) > 1e9) return 'Each value is between 1 and 10^9, written without leading zeros.';
    if (nodes === 0 && depth !== 0) return 'The root comes first, with no dashes.';
    if (nodes > 0 && (depth === 0 || depth > children.length)) return 'Each node after the root must be one level below an earlier open node.';
    children.length = depth;
    if (depth > 0) {
      if (children[depth - 1] === 2) return 'A node can have at most two children.';
      children[depth - 1]++;
    }
    children.push(0);
    nodes++;
  }
  if (nodes < 1 || nodes > 1000) return 'The tree has between 1 and 1000 nodes.';
  return null;
}

