function recoverFromPreorder(traversal) {
  // Split into (depth, value) tokens, then rebuild recursively: a subtree at depth d takes the next
  // token only if that token sits at depth d.
  const tokens = [...traversal.matchAll(/(-*)(\d+)/g)].map(m => [m[1].length, Number(m[2])]);
  let pos = 0;
  const build = depth => {
    if (pos >= tokens.length || tokens[pos][0] !== depth) return null;
    const node = new TreeNode(tokens[pos][1]);
    pos++;
    node.left = build(depth + 1);
    node.right = build(depth + 1);
    return node;
  };
  return build(0);
}

