function generate(rand, size) {
  const int = (lo, hi) => lo + Math.floor(rand() * (hi - lo + 1));
  const value = () => {
    const r = rand();
    if (r < 0.1) return int(1, 1e9);
    if (r < 0.15) return 1e9;
    if (r < 0.5) return int(1, 9);
    return int(1, size === 'large' ? 999 : 99);
  };
  // Writes a random tree of count nodes in preorder; a lone child always becomes the left one.
  const build = (count, depth, balanced) => {
    if (count === 0) return '';
    const rest = count - 1;
    let left = balanced ? Math.floor(rest / 2) + int(-Math.floor(rest / 4), Math.floor(rest / 4)) : int(0, rest);
    let right = rest - left;
    if (left === 0) { left = right; right = 0; }
    return '-'.repeat(depth) + value() + build(left, depth + 1, balanced) + build(right, depth + 1, balanced);
  };
  if (size === 'small') {
    if (rand() < 0.15) {
      // A short chain of left children, sometimes with right leaves.
      const leaves = rand() < 0.5;
      let text = '';
      const length = int(1, 6);
      for (let d = 0; d < length; d++) text += '-'.repeat(d) + value();
      if (leaves) for (let d = length - 2; d >= 0; d--) text += '-'.repeat(d + 1) + value();
      return [text];
    }
    return [build(int(1, 10), 0, rand() < 0.3)];
  }
  if (rand() < 0.25) {
    // A left spine where each spine node also has a right leaf.
    const spine = int(60, 85);
    let text = '';
    for (let d = 0; d < spine; d++) text += '-'.repeat(d) + value();
    for (let d = spine - 2; d >= 0; d--) text += '-'.repeat(d + 1) + value();
    return [text];
  }
  let count = int(500, 1000);
  for (;;) {
    const text = build(count, 0, true);
    if (text.length <= 10000) return [text];
    count = Math.floor(count * 0.85);
  }
}
